+// Resolve only known task IDs. A historical review is read-only; only the
+// current task and the single pending interrupted review can accept captures.
+func (state hookState) reviewForTask(taskID []string) (reviewState, string, error) {
+	if len(taskID) == 0 || taskID[0] == "" || taskID[0] == state.Task {
+		return state.currentReview(), "current", nil
+	}
+	if state.Pending != nil && state.Pending.Task == taskID[0] {
+		return *state.Pending, "pending", nil
+	}
+	if review, ok := state.History[taskID[0]]; ok {
+		return review, "history", nil
+	}
+	return reviewState{}, "", fmt.Errorf("unknown task ID: %s", taskID[0])
+}
